/** Original Midnight Ink educational content. Paper and synthetic skin only.
 * No manufacturer specifications or external review claims are implied. */
export type LearningModule = { id: string; title: string; description: string; number: number };
export type Lesson = { id: string; moduleId: string; title: string; summary: string; minutes: number; objectives: string[]; explanation: string[]; practice: string[]; equipment: string[]; mistakes: string[]; question: string; answer: string; referenceIds: string[] };
export type Exercise = { id: string; title: string; category: string; minutes: number; description: string; instructions: string[]; equipment: string[]; goals: string[] };
export type TechniqueCard = { id: string; title: string; category: string; level: string; description: string; sourceUrl: string | null; attribution: string; reviewStatus: string; lastReviewed: string | null; lessonIds: string[]; compatibility: string[]; safetyNotes: string[] };

