export const exercises: Exercise[] = [
  { id: "straight-lines", title: "Straight lines", category: "Linework", minutes: 15, description: "A baseline study of planned paths, smooth movement, and deliberate endpoints.", instructions: ["Begin on paper. Set up a comfortable supported posture and mark each endpoint.", "Rehearse above the page, then draw each path once. Pause and reset between marks.", "Complete three sets of five. Keep the first attempts visible and record one specific observation.", "For a separate synthetic study, use only known equipment instructions, fresh single-use supplies, and planned sharps disposal."], equipment: ["Printed worksheet or paper", "Drawing pen", "Optional documented synthetic practice setup"], goals: ["Describe smoothness and endpoint accuracy separately", "Choose one movement variable for the next attempt"] },
  { id: "parallel-lines", title: "Parallel lines", category: "Linework", minutes: 15, description: "Make the gaps as intentional as the marks.", instructions: ["Use the worksheet guides to plan five equally spaced paths.", "Draw one line at a time without bending the next line to compensate for the last.", "Repeat without guides. Compare the negative-space strips between lines.", "Record whether spacing, direction, or starts and stops need the next focused set."], equipment: ["Worksheet", "Drawing pen", "Ruler for planning"], goals: ["Maintain deliberate spacing", "Distinguish direction drift from wavering"] },
  { id: "circles", title: "Circles", category: "Linework", minutes: 15, description: "Plan an even contour and inspect the closure honestly.", instructions: ["Rehearse each circle above the paper before making the mark.", "Draw six circles once each, choosing a comfortable page orientation.", "Mark where each circle closes and compare the tangent, gap, and overlap.", "Keep imperfect joins visible. Write one observation without retracing the circle."], equipment: ["Circle worksheet", "Drawing pen"], goals: ["Recognize uneven curvature", "Compare closure quality"] },
  { id: "s-curves", title: "S-curves", category: "Linework", minutes: 18, description: "Practice smooth directional changes through an open center transition.", instructions: ["Locate the start, center transition, and end of each path.", "Rehearse the full movement; rotate the page if the curve feels strained.", "Draw each curve once and compare any kink or flat section in the middle.", "Repeat a second set with only the page orientation changed and record the difference."], equipment: ["S-curve worksheet", "Drawing pen"], goals: ["Keep the inflection smooth", "Use comfortable movement planning"] },
  { id: "corners", title: "Corners & joins", category: "Linework", minutes: 15, description: "Bring planned segments together without hiding the meeting point.", instructions: ["Mark each corner point and the endpoints of its two segments.", "Draw straight segments that meet deliberately; pause and reset between shapes.", "Compare gaps, overshoots, and unplanned rounding as separate observations.", "Make a new set using the most comfortable page angle."], equipment: ["Corner worksheet", "Drawing pen"], goals: ["Plan segment endpoints", "Keep corners legible"] },
  { id: "solid-fills", title: "Controlled solid fills", category: "Blackwork", minutes: 20, description: "Plan small areas and evaluate coverage independently from the edge.", instructions: ["Begin with a black drawing marker on paper and choose one bounded shape.", "Divide the shape mentally into small sections and fill in an orderly sequence.", "Inspect interior gaps and boundary overshoot separately.", "On a separate synthetic study, stop any area that visibly deteriorates; document rather than add repeated corrective passes."], equipment: ["Fill worksheet", "Black drawing marker", "Optional documented synthetic setup"], goals: ["Develop visually consistent coverage", "Preserve deliberate boundaries", "Record a stopping rule"] },
  { id: "gradients", title: "Shading gradients", category: "Shading", minutes: 20, description: "Build a paper value plan from dark through middle values to light.", instructions: ["Use a pencil. Label the dark, middle, and light zones before drawing.", "Create three studies using the same size rectangle and drawing tool.", "Compare transition width, visible banding, and the darkest value separately.", "Choose one change for the next attempt; this exercise provides no human-skin or ink-mixing preset."], equipment: ["Gradient worksheet", "Pencil", "Eraser"], goals: ["Preserve a clear light zone", "Recognize and describe tonal bands"] },
  { id: "stencil-tracing", title: "Simple stencil tracing", category: "Stencils", minutes: 20, description: "Practice following a clear original guide and checking orientation.", instructions: ["Use the original geometric-leaf worksheet or a permitted original design.", "Check orientation, actual printed size, and clear separation of guide lines.", "Trace on paper first, planning starts and stops before drawing.", "For a synthetic transfer study, follow the specific material instructions and compare clarity against the master before any powered work."], equipment: ["Stencil worksheet", "Drawing pen", "Optional compatible synthetic transfer materials"], goals: ["Maintain clear guide alignment", "Verify orientation before tracing", "Document transfer clarity separately from line quality"] },
];

const card = (id: string, title: string, category: string, description: string, lessonIds: string[], compatibility: string[], safetyNotes: string[]): TechniqueCard => ({ id, title, category, level: "Beginner", description, sourceUrl: null, attribution: "Original Midnight Ink educational content · AIBRY Labs", reviewStatus: "Original educational guidance · not externally reviewed", lastReviewed: null, lessonIds, compatibility, safetyNotes });
export const techniqueCards: TechniqueCard[] = [
  card("practice-boundary", "Paper and synthetic skin are learning materials", "Safety", "Paper develops visual judgment and movement planning. Synthetic sheets can support equipment-handling studies, but they do not reproduce tissue behavior, healing, pain, infection risk, or professional working conditions. Learning progress is a record of study, never a certification or permission to tattoo people.", ["synthetic-materials", "licensing-mentorship"], ["Paper", "Synthetic practice materials"], ["Human-skin work requires appropriate training, supervision, infection control, and applicable licensing.", "No photo or AI response establishes competency or biological safety."]),
  card("machine-unknown", "Keep unknown equipment facts unknown", "Equipment", "Record the exact manufacturer and model when known. Pen-style appearance does not identify stroke, electrical compatibility, operating limits, or suitable controls. Manufacturer guidance must come from the correct manual. Never infer a universal human-skin voltage or penetration depth from a cartridge code, photograph, or another machine.", ["machine-motion", "rotary-pens", "controls-workspace"], ["Machine inventory", "Model-specific documentation"], ["Use an unpowered inspection when specifications are unknown.", "Do not use damaged power systems or guess adapter compatibility."]),
  card("cartridge-codes", "Read common cartridge code conventions", "Equipment", "Common codes combine diameter shorthand, needle count, and grouping. 1203RL commonly means nominal 0.35 mm, three needles, round liner; 1205RL means five in that convention; 1205M1 means nominal 0.35 mm, five, magnum; 1007RM commonly means nominal 0.30 mm, seven, curved magnum. These interpretations do not verify measured dimensions, taper, brand construction, sterile status, or settings. Ambiguous codes require manufacturer documentation.", ["needle-groupings", "cartridge-anatomy", "magnum-markmaking"], ["Supported common codes", "Manufacturer packaging and manuals"], ["A code is not a safe-use prescription.", "Do not infer sterile status from a photo or short code."]),
  card("workspace-zones", "Map clean-to-used contact paths", "Safety", "Rehearse your workflow with a capped pen before opening supplies. Plan unused supplies, the working area, and waste so that objects do not repeatedly cross between them. Include phones, lamp controls, notebooks, and drawer handles in the contact map. A gloved hand can transfer contamination just like another touched surface; gloves alone do not validate a workflow.", ["controls-workspace", "cross-contamination"], ["Paper rehearsal", "Synthetic practice planning"], ["Professional infection control requires appropriate training and validated procedures.", "A tidy desk is not evidence of sterility."]),
  card("movement-planning", "Plan the path before making the mark", "Linework", "Choose endpoints, rehearse the movement above the paper, and rotate the sheet to fit a comfortable range of motion. Use relaxed support rather than squeezing harder. Start with manageable lengths and pause between sets. Compare the start, middle, and finish independently, preserving the first attempt so the next exercise has real evidence.", ["supported-position", "straight-lines", "curves-s-curves", "circles-corners"], ["Pencil", "Drawing pen", "Paper worksheets", "Synthetic studies with known setup"], ["Stop and reset if a posture causes pain.", "Do not translate a paper grip or movement into a universal human-skin prescription."]),
  card("single-variable", "Change one documented variable at a time", "Practice", "A useful comparison controls what it can: surface, exercise size, light, drawing tool, and the chosen movement condition. Write a visible observation first and choose one change, such as page orientation or line length. Changing everything together makes it difficult to learn what helped. Machine settings, if recorded, are user-reported context rather than coach-verified recommendations.", ["parallel-spacing", "starts-stops-troubleshooting", "stippling"], ["All paper drills", "Synthetic practice logs"], ["Do not experiment on human skin.", "Stop damaged synthetic areas rather than adding corrective passes."]),
  card("negative-spacing", "Study the space between parallel lines", "Linework", "Judge the negative-space strips alongside the marks. Plan endpoint positions and compare whether gaps converge or widen. A straighter neighboring line does not repair an earlier line; keep each attempt visible. Use one guided set and one unguided set as separate conditions rather than pretending they are identical tests.", ["parallel-spacing"], ["Paper", "Parallel-line worksheet"], ["No practice score establishes professional readiness."]),
  card("starts-stops", "Describe starts, joins, and stops precisely", "Linework", "Separate endpoint placement, tangent direction, width change, and overlap. ‘The final third becomes wider’ is a useful observation; ‘the depth was wrong’ is an unsupported diagnosis from a photo alone. Circle closures and corner joins are good paper studies because they make small planning differences visible.", ["circles-corners", "starts-stops-troubleshooting"], ["Paper", "Circle and corner studies", "Practice-photo self-assessment"], ["A photo cannot establish physical penetration, exact settings, or sterility."]),
  card("surface-damage", "Stop and document synthetic surface deterioration", "Practice", "Tearing, roughness, and texture changes in a synthetic sheet are observations, not measurements of tissue injury. Set a stopping rule before the study. If the surface changes visibly or equipment behaves unpredictably, stop that area and review the setup using actual instructions. Preserve evidence rather than repeatedly covering a weak result.", ["synthetic-materials", "solid-fill", "passes-surface"], ["Synthetic practice sheets", "Practice logs"], ["Do not infer human-tissue safety from a synthetic result.", "Disposable cartridges remain single-use."]),
  card("silhouette-first", "Resolve the silhouette before adding detail", "Drawing", "Reduce an original motif to a few large masses and test it filled black. Readability should not depend on tiny texture. Treat the gaps as designed shapes and compare the motif at arm’s length. If reducing the size closes important spaces, simplify rather than adding contrast indiscriminately.", ["shape-language", "contrast-silhouette", "original-motifs"], ["Paper", "Black marker", "Design Studio"], ["A clear silhouette is a design study, not a prediction of a healed tattoo."]),
  card("line-hierarchy", "Give each line weight a job", "Drawing", "Start with two widths: a structural contour and a lighter internal detail line. Use them consistently so the viewer can identify the main shape before reading texture. Digital brush widths and drawing pen sizes do not map directly to cartridge configurations. Inspect the hierarchy at intended print size.", ["line-hierarchy", "flash-sheet"], ["Drawing pens", "Digital vector strokes"], ["Use drawing studies to plan visual roles rather than select human-skin equipment presets."]),
  card("size-check", "Print at actual size", "Design", "Place artwork within measured dimensions and compare more than one printed size. A zoomed screen can hide crowding. At smaller sizes, remove redundant marks and preserve deliberate gaps instead of shrinking every detail proportionally. Check printer scaling and retain an editable original so revisions remain possible.", ["practical-size", "stencil-lines", "contrast-silhouette"], ["Paper", "Ruler", "Printable stencil layout"], ["An export is not a professional suitability assessment."]),
  card("composition-masses", "Balance large masses in thumbnails", "Drawing", "Make several small versions before refining a composition. Compare the focal area, dark mass distribution, and the direction of major curves. A heavy black shape can outweigh a much larger light area. Leave breathing room and test whether the arrangement still reads without fine marks.", ["composition", "flash-sheet"], ["Paper thumbnails", "Digital sketches"], ["Use original or permitted references."]),
  card("coverage-grid", "Separate coverage from edge control", "Blackwork", "In a bounded fill study, inspect the interior and perimeter separately. Use small planned sections on paper to compare gaps, streaks, and overshoot without hiding weak attempts. A broad marker can explore orientation and overlap visually, but it does not simulate a needle grouping in tissue.", ["magnum-markmaking", "solid-fill"], ["Paper", "Broad marker", "Synthetic studies with documented setup"], ["Repeated passes can deteriorate synthetic material; stop and document.", "No universal settings are supplied."]),
  card("value-planning", "Plan value zones before a transition", "Shading", "Begin with discrete light, middle, and dark values. In a gradient, reserve enough space for intermediate tones and preserve the lightest zone. In stippling, vary comparable mark density rather than making every dot larger. Compare studies with consistent lighting and media so visual differences remain useful.", ["tonal-values", "gradient-planning", "stippling"], ["Pencil", "Drawing pen", "Paper value studies"], ["This is visual planning, not a human-skin shading or ink-dilution recipe."]),
  card("stencil-preparation", "A stencil is a deliberate guide", "Stencils", "Prioritize clear contours, major internal boundaries, and useful landmarks. Remove stray or duplicate lines and check actual-size readability. A raster reference remains limited by its resolution, while vector-compatible paths can scale cleanly. Save the editable original before export and follow the exact transfer materials’ instructions for synthetic studies.", ["simplify-artwork", "stencil-lines", "transfer-practice"], ["Original drawings", "SVG paths", "PNG exports", "Compatible synthetic transfer materials"], ["Automatic contrast does not certify professional application readiness.", "Synthetic transfer instructions do not instruct human-skin preparation."]),
  card("mirror-check", "Rehearse orientation with an asymmetric design", "Stencils", "A horizontal mirror reverses left and right, including lettering. Label the intended final orientation on the master and test the specific transfer method on paper using a visibly asymmetric motif. Do not assume every printer or transfer product introduces the same reversal.", ["mirror-orientation", "transfer-practice"], ["Paper tests", "Design Studio mirror control", "Synthetic transfer studies"], ["Confirm orientation before any tracing or powered synthetic work."]),
  card("placement-paper", "Study curvature on a paper mock form", "Design", "Wrap a paper motif around a simple cylinder and compare it from several viewpoints. Record which shapes disappear or look crowded rather than judging a single flat screenshot. This teaches visual composition without pretending to assess a person’s anatomy, skin condition, or procedural suitability.", ["placement-study"], ["Paper", "Clean mock forms"], ["Actual body placement needs consent and qualified professional judgment."]),
  card("infection-awareness", "Appearance does not establish infection status", "Safety", "Bloodborne pathogens can be transmitted through exposure pathways involving contaminated sharps, mucous membranes, or broken skin. Do not rely on appearances to decide whether precautions are necessary. Professional infection-control training and an appropriate exposure-response plan are separate requirements from this educational app.", ["bloodborne-fundamentals", "cross-contamination"], ["Safety education", "Supervised training preparation"], ["This content is not certification or a complete exposure-response protocol.", "For an actual exposure, seek prompt professional medical evaluation through the relevant procedure."]),
  card("sharps-basics", "Plan single-use sharps disposal first", "Safety", "Before opening a disposable cartridge, locate an appropriate closable puncture-resistant sharps container and understand its fill limits. Keep exposed sharps controlled and follow local disposal rules. Synthetic practice does not make sharing, cleaning for reuse, saving for another session, or placing loose cartridges in ordinary waste acceptable.", ["cartridge-anatomy", "disposables-sharps"], ["All powered synthetic practice"], ["Never reuse disposable cartridges.", "Keep sharps away from children and pets and check official local disposal requirements."]),
  card("ink-uncertainty", "Unverified ink stays practice-only", "Safety", "Record brand, lot, expiration, intended purpose, and storage history only when known. A bottle label or seller statement does not prove suitability for human tattooing. The sample MATOENT assortment is explicitly user-reported and practice-only because human-use suitability is unverified. Keep missing facts visible and never treat the inventory as certification.", ["ink-safety"], ["Ink inventory", "Synthetic practice only for unverified products"], ["Do not return dispensed ink to its bottle.", "Professional product selection requires appropriate official guidance and supervised training."]),
  card("originality-ethics", "Respect creative work and tell the truth about experience", "Professional", "Use original drawings or references you have permission to use, and retain source attribution. An online image is not automatically free to copy. Describe your learning level honestly, obtain permission before sharing identifiable material, and never represent lesson progress or AI feedback as professional qualification.", ["original-motifs", "flash-sheet", "ethics-consent"], ["All original design work", "Portfolio preparation"], ["Consent, intellectual property, and privacy still apply to practice work."]),
  card("photo-comparison", "Compare photos under similar conditions", "Practice", "Use comparable crops, orientation, scale, surface material, and even lighting when reviewing two attempts. Describe visible consistency, smoothness, coverage, edges, and surface changes yourself. Differences in lighting or focus can change apparent quality. Keep uncertainty explicit rather than inventing depth, settings, or biological conclusions.", ["tonal-values", "starts-stops-troubleshooting"], ["Practice-photo comparison", "Self-assessment"], ["A photo cannot establish sterility, actual penetration, or professional readiness."]),
  card("photo-privacy", "Choose deliberately before sharing an image", "Privacy", "Use photos of your own practice or material you have permission to share. Keep faces, names, addresses, and other identifiers out of the frame. Local storage and an external provider are different destinations: sending an image outside the app requires a clear deliberate action and disclosure. Deleting a local record cannot recall a copy already sent elsewhere.", ["ethics-consent"], ["Practice photos", "Reference-image uploads"], ["Do not share identifying or third-party material without appropriate permission."]),
  card("training-pathway", "Verify local requirements and seek qualified supervision", "Professional", "Identify the official regulator or public-health authority for the place where you intend to train. Requirements vary and can change. Record unanswered questions and bring dated paper and synthetic studies to a qualified mentor. A portfolio can demonstrate deliberate practice, but only appropriate training and assessment can address professional responsibilities.", ["bloodborne-fundamentals", "licensing-mentorship"], ["Training plans", "Practice portfolios"], ["Midnight Ink does not grant licenses, certifications, or authorization to tattoo people."]),
];
